import Link from "next/link";
import type { Metadata } from "next";
import { GameLandingCombined } from "@/components/marketing/gamelanding/GameLandingCombined";
import { PREVIEW_GAMES } from "@/components/marketing/gamelanding/data";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { Section, SectionTitle } from "@/components/marketing/primitives";
import { FaqJsonLd, ProductOffersJsonLd, APP_URL } from "@/components/marketing/StructuredData";

/**
 * LIVE — flagship "Combined" game-landing design, 2026-09-14 SEO gap-fill.
 *
 * PREVIEW_GAMES.squad was authored directly from the real seeded GamePlan
 * rows (prisma/seed-wave8-games.ts — 16GB/50-player $29.99, 24GB/80-player
 * $44.99 popular, 32GB/100-player $59.99), so no price override is needed
 * here.
 *
 * FAQ + related-links sections below follow the same pattern as
 * rust-server-hosting/page.tsx, since GameLandingCombined doesn't render its
 * own FAQ/related sections.
 */

export const metadata: Metadata = {
  title: "Squad Server Hosting — Instant Setup",
  description:
    "Managed Squad server hosting from $29.99/mo. Full RCON access, custom layer rotation, and instant setup on a low-latency Singapore network.",
  alternates: { canonical: "/squad-server-hosting" },
  openGraph: {
    type: "article",
    title: "Squad Server Hosting — Instant Setup",
    description:
      "Managed Squad hosting: full RCON access, custom layer rotation, and instant setup on a low-latency Singapore network. From $29.99/mo.",
    url: `${APP_URL}/squad-server-hosting`,
  },
};

const GAME = PREVIEW_GAMES.squad;

const FAQ = [
  {
    q: "What is Squad?",
    a: "Squad is a large-scale, realistic multiplayer military shooter built around combined-arms teamwork — infantry, vehicles, and a persistent Squad Lead/Commander structure across matches that can run 50 to 100 players.",
  },
  {
    q: "Which plan do I need?",
    a: "The 16 GB / 50-player Skirmish plan at $29.99 suits an infantry-focused server without vehicles maxed out. The 24 GB / 80-player Combined Arms plan at $44.99 is our popular pick for a full server running vehicles and logistics. Choose the 32 GB / 100-player Large Op plan at $59.99 for a large, active community running competitive layers.",
  },
  {
    q: "Why does Squad cost more than most game servers?",
    a: "Squad's 50-100 player combined-arms matches are genuinely CPU- and RAM-heavy — far more than a typical survival or sandbox title — so plans start higher to guarantee the resources a real match needs, not because of a markup.",
  },
  {
    q: "Is this a managed server or a VPS I set up myself?",
    a: "It's a fully managed Squad server — no Linux setup or SquadJS configuration required from you. Order a plan and it's provisioned and online in minutes, ready to load a layer.",
  },
  {
    q: "How quickly is my server ready?",
    a: "Setup is instant — your Squad server is provisioned and online within minutes of ordering, so your squad leads can start running layers the same day.",
  },
];

const RELATED = [
  { label: "All game servers", href: "/game-servers" },
  { label: "Insurgency: Sandstorm hosting", href: "/insurgency-sandstorm-server-hosting" },
  { label: "Killing Floor 2 hosting", href: "/killing-floor-2-server-hosting" },
  { label: "Pricing", href: "/pricing" },
];

export default function SquadServerHostingPage() {
  return (
    <>
      <FaqJsonLd items={FAQ} />
      <ProductOffersJsonLd
        name="Nxeon Squad Server Hosting"
        description={GAME.deck}
        url={`${APP_URL}/game-servers`}
        offers={GAME.plans.map((p) => ({
          name: `${GAME.name} ${p.tier} (${p.ram})`,
          price: parseFloat(p.price.replace(/[^0-9.]/g, "")),
        }))}
      />

      <GameLandingCombined game={GAME} reviewBadges={<ReviewBadges />} />

      {/* FAQ */}
      <Section tone="base" size="md">
        <SectionTitle eyebrow="FAQ" title="Questions, answered" />
        <div className="mx-auto mt-10 max-w-3xl space-y-3">
          {FAQ.map((f) => (
            <details key={f.q} className="card group">
              <summary className="cursor-pointer list-none font-medium text-white marker:content-none">
                <span className="flex items-center justify-between gap-4">
                  {f.q}
                  <span className="text-slate-500 transition-transform group-open:rotate-45">+</span>
                </span>
              </summary>
              <p className="mt-3 text-sm leading-relaxed text-slate-400">{f.a}</p>
            </details>
          ))}
        </div>
      </Section>

      {/* Related */}
      <Section tone="base" size="sm">
        <div className="mx-auto flex max-w-3xl flex-wrap items-center justify-center gap-2">
          <span className="text-xs font-semibold uppercase tracking-wider text-slate-500">Related</span>
          {RELATED.map((r) => (
            <Link
              key={r.href}
              href={r.href}
              className="rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-sm text-slate-300 transition-colors hover:border-white/20 hover:text-white"
            >
              {r.label}
            </Link>
          ))}
        </div>
      </Section>
    </>
  );
}

